public protocol MuxClientProtocol: AnyObject, Sendable {
    
    /**
     * 指定ペインを購読開始し、要求サイズへ Resize する。以後 on_snapshot が届く。
     */
    func attach(paneId: UInt64, cols: UInt32, rows: UInt32) throws 
    
    /**
     * 接続を閉じる。エンジンスレッドを停止させ、ソケットを shutdown する。
     */
    func disconnect() 
    
    /**
     * 指定ペインを kill する（自分でスポーンしたペインの後片付け用）。
     */
    func kill(paneId: UInt64) throws 
    
    /**
     * 全ペインの一覧を取得する。
     */
    func listPanes() throws  -> [PaneInfo]
    
    /**
     * ペインをリサイズする。
     */
    func resize(paneId: UInt64, tabId: UInt64, cols: UInt32, rows: UInt32) throws 
    
    /**
     * キー入力（生バイト）をペインへ送る（WriteToPane）。
     */
    func sendInput(paneId: UInt64, data: Data) throws 
    
    /**
     * 隔離用に新規ペインをスポーンする（スモーク/将来のiOS新規タブ用）。
     */
    func spawn(workspace: String, cols: UInt32, rows: UInt32) throws  -> SpawnInfo
    
}
